#include <iostream>
#include <vector>
#include <string>

int main() {
    std::vector<int> leftBracketPositions;
    std::vector<int> rightBracketPositions;
    int totalPairs;
    std::cin >> totalPairs;
    std::string sequence;
    std::cin >> sequence;

    for (int i = 0; i < totalPairs; i++) {
        if (sequence[i] == '(') {
            leftBracketPositions.push_back(i);
        } else if (sequence[i] == ')') {
            rightBracketPositions.push_back(i);
        }
    }

    int totalWords = 0;
    auto getSegments = [&](const std::string& s, const std::vector<int>& starts, const std::vector<int>& ends) {
        std::vector<std::string> segments;
        for (size_t i = 0; i < starts.size(); i++) {
            segments.push_back(s.substr(starts[i] + 1, ends[i] - starts[i] - 1));
        }
        return segments;
    };

    for (const auto& segment : getSegments(sequence, leftBracketPositions, rightBracketPositions)) {
        size_t start = 0;
        size_t end = 0;
        size_t pos = 0;
        while (pos != std::string::npos) {
            pos = segment.find('_', start);
            std::string part;
            if (pos == std::string::npos) {
                part = segment.substr(start);
            } else {
                part = segment.substr(start, pos - start);
            }
            if (!part.empty()) {
                totalWords++;
            }
            start = (pos == std::string::npos) ? segment.length() : pos + 1;
        }
    }

    int maxWordLength = 0;
    leftBracketPositions.push_back(sequence.length());
    rightBracketPositions.insert(rightBracketPositions.begin(), 0);
    int startIdx = (sequence[0] == '(') ? 1 : 0;

    for (size_t i = startIdx; i < rightBracketPositions.size(); i++) {
        std::string segment;
        if (sequence[rightBracketPositions[i]] == ')') {
            segment = sequence.substr(rightBracketPositions[i] + 1, leftBracketPositions[i] - rightBracketPositions[i] - 1);
        } else {
            segment = sequence.substr(rightBracketPositions[i], leftBracketPositions[i] - rightBracketPositions[i]);
        }
        for (size_t j = 0; j < segment.length(); ) {
            size_t next_pos = segment.find('_', j);
            std::string part;
            if (next_pos == std::string::npos) {
                part = segment.substr(j);
                j = segment.length();
            } else {
                part = segment.substr(j, next_pos - j);
                j = next_pos + 1;
            }
            if (part.length() > maxWordLength && part.find('(') == std::string::npos && part.find(')') == std::string::npos) {
                maxWordLength = part.length();
            }
        }
    }

    std::cout << maxWordLength << " " << totalWords << std::endl;
    return 0;
}

